// FirewallServiceHandler is an implementation of the panel.agent.v1.FirewallService service.
type FirewallServiceHandler interface {
	// 读取防火墙子系统状态（system/forward/docker）。
	BaseInfo(context.Context, *connect.Request[v1.FirewallBaseInfoRequest]) (*connect.Response[v1.FirewallBaseInfo], error)
	// 启停防火墙或切换禁 ping 策略。
	Operate(context.Context, *connect.Request[v1.FirewallLifecycleRequest]) (*connect.Response[v1.FirewallTaskResponse], error)
	// 读取端口转发子系统状态。
	GetForwardBase(context.Context, *connect.Request[v1.GetForwardBaseRequest]) (*connect.Response[v1.FirewallSubsystem], error)
	// 分页查询端口转发规则。
	SearchForwardRules(context.Context, *connect.Request[v1.SearchForwardRulesRequest]) (*connect.Response[v1.SearchForwardRulesResponse], error)
	// 新增或删除端口转发规则。
	OperateForwardRules(context.Context, *connect.Request[v1.OperateForwardRulesRequest]) (*connect.Response[v1.FirewallTaskResponse], error)
	// 初始化并启用端口转发。
	EnableForwarding(context.Context, *connect.Request[v1.EnableForwardingRequest]) (*connect.Response[v1.FirewallTaskResponse], error)
	// 初始化、绑定或解绑防火墙过滤链。
	OperateFilterChain(context.Context, *connect.Request[v1.OperateFilterChainRequest]) (*connect.Response[v1.FirewallTaskResponse], error)
	// 重置某个子系统的规则，可先备份。
	ResetRules(context.Context, *connect.Request[v1.ResetFirewallRulesRequest]) (*connect.Response[v1.ResetFirewallRulesResponse], error)
	// 读取原生区域/应用的规则详情。
	GetNativeDetail(context.Context, *connect.Request[v1.GetFirewallNativeDetailRequest]) (*connect.Response[v1.FirewallNativeDetailResponse], error)
	// 批量创建防火墙规则。
	CreateRules(context.Context, *connect.Request[v1.CreateFirewallRulesRequest]) (*connect.Response[v1.CreateFirewallRulesResponse], error)
	// 批量删除防火墙规则。
	DeleteRules(context.Context, *connect.Request[v1.DeleteFirewallRulesRequest]) (*connect.Response[v1.DeleteFirewallRulesResponse], error)
	// 修改单条规则，或只改描述/排序。
	UpdateRule(context.Context, *connect.Request[v1.UpdateFirewallRuleRequest]) (*connect.Response[v1.UpdateFirewallRuleResponse], error)
	// 调整单条规则的位置或优先级。
	ReorderRule(context.Context, *connect.Request[v1.ReorderFirewallRuleRequest]) (*connect.Response[v1.ReorderFirewallRuleResponse], error)
	// 读取防火墙设置（后端选择、白名单、端口等）。
	GetSettings(context.Context, *connect.Request[v1.GetFirewallSettingsRequest]) (*connect.Response[v1.FirewallSettings], error)
	// 新增端口白名单。
	CreateWhitelist(context.Context, *connect.Request[v1.CreateFirewallWhitelistRequest]) (*connect.Response[v1.CreateFirewallWhitelistResponse], error)
	// 修改端口白名单。
	UpdateWhitelist(context.Context, *connect.Request[v1.UpdateFirewallWhitelistRequest]) (*connect.Response[v1.UpdateFirewallWhitelistResponse], error)
	// 删除端口白名单。
	DeleteWhitelist(context.Context, *connect.Request[v1.DeleteFirewallWhitelistRequest]) (*connect.Response[v1.DeleteFirewallWhitelistResponse], error)
	// 切换某子系统的防火墙后端。
	OperateBackend(context.Context, *connect.Request[v1.OperateFirewallBackendRequest]) (*connect.Response[v1.OperateFirewallBackendResponse], error)
	// 开启或关闭防火墙 IPv6 支持。
	OperateIPv6(context.Context, *connect.Request[v1.OperateFirewallIPv6Request]) (*connect.Response[v1.FirewallTaskResponse], error)
	// 初始化、修复或绑定某个地址族的防火墙链。
	OperateFamily(context.Context, *connect.Request[v1.OperateFirewallFamilyRequest]) (*connect.Response[v1.FirewallTaskResponse], error)
	// 读取 Docker 端口防护总览。
	ListDockerPorts(context.Context, *connect.Request[v1.GetDockerPortsRequest]) (*connect.Response[v1.DockerGuardOverview], error)
	// 列出 Docker 已发布端口及其防护状态。
	ListDockerEndpoints(context.Context, *connect.Request[v1.GetDockerEndpointsRequest]) (*connect.Response[v1.DockerEndpointsResponse], error)
	// 初始化或绑定 Docker 端口防护。
	OperateDocker(context.Context, *connect.Request[v1.OperateDockerGuardRequest]) (*connect.Response[v1.FirewallTaskResponse], error)
	// 批量新增或更新 Docker 端口防护策略。
	UpsertDockerPolicies(context.Context, *connect.Request[v1.UpsertDockerPoliciesRequest]) (*connect.Response[v1.FirewallTaskResponse], error)
	// 批量删除 Docker 端口防护策略。
	DeleteDockerPolicies(context.Context, *connect.Request[v1.DeleteDockerPoliciesRequest]) (*connect.Response[v1.FirewallTaskResponse], error)
	// 列出防火墙规则备份文件。
	ListRuleBackups(context.Context, *connect.Request[v1.ListFirewallBackupsRequest]) (*connect.Response[v1.FirewallRuleBackups], error)
	// 分页查询防火墙规则清单。
	Inventory(context.Context, *connect.Request[v1.FirewallInventoryRequest]) (*connect.Response[v1.FirewallInventory], error)
}

